        "/new" -> {
            newSession()
            _agentMessages.update { it + AgentItem.Info("Новая сессия${projectName()?.let { " для проекта $it" } ?: ""}.") }
            return
        }
        "/init" -> {
            if (!requireConfigured()) return
            _agentMessages.update { it + AgentItem.User("/init") }
            runAgentTurn(
