    private fun performTurn(
        run: SessionRun,
        info: Sessions.SessionInfo,
        userText: String,
        config: AgentSettings.Config,
        subagent: OpenCodeTools.TaskRequest?,
        allowedTools: Set<String>?,
    ) {
        val start = System.currentTimeMillis()
